<template>
  <section v-if="state.selected" class="copy-panel" aria-label="区块协作">
    <header class="copy-panel__heading"><div><small>当前选中区块</small><h2>{{ state.selected.label }}</h2></div><button type="button" aria-label="关闭区块协作" :disabled="state.busy" @click="close">×</button></header>
    <p class="copy-panel__context">{{ state.selected.context.page }}<span v-if="state.selected.context.state"> · {{ state.selected.context.state }}</span></p>
    <div class="copy-panel__tabs" role="tablist" aria-label="区块协作方式"><button v-if="editable" type="button" role="tab" :aria-selected="state.tab==='edit'" @click="state.tab='edit'">文案</button><button type="button" role="tab" :aria-selected="state.tab==='comments'" @click="state.tab='comments'">备注 / 评论 <span v-if="state.comments.length">{{ state.comments.length }}</span></button><button v-if="editable" type="button" role="tab" :aria-selected="state.tab==='history'" @click="state.tab='history'">版本记录</button></div>
    <div v-if="!reviewable" class="copy-panel__locked"><p>{{ state.unavailable?'共享协作服务尚未连接。':'使用协作链接后，可在此查看和提交评论。' }}</p><small>请向原型维护者获取协作链接。</small></div>
    <template v-else>
      <label class="copy-panel__author">显示名称<input v-model="state.actor" maxlength="40" placeholder="用于修改与评论记录" :disabled="state.busy"/><small>此名称由协作者填写。</small></label>
      <form v-if="state.tab==='edit'&&editable" class="copy-panel__form" @submit.prevent="save">
        <p class="copy-panel__hint">修改会即时预览，保存仅更新当前区块。</p>
        <label v-for="field in state.fields" :key="field.key" :data-copy-field="field.key" class="copy-field" :class="{'has-error':state.errors[field.key]}"><span>{{ field.label }}<small>{{ Array.from(state.draft[field.key]||'').length }} / {{ field.max }}</small></span><textarea :value="state.draft[field.key]" :rows="field.max>160?3:2" :disabled="state.busy" :aria-invalid="!!state.errors[field.key]" @input="edit(field.key,$event.target.value)"/><small v-if="state.errors[field.key]" class="copy-field__error">{{ state.errors[field.key] }}</small><small v-else-if="field.inherit">留空时沿用公共文案。</small><small v-else-if="field.tokens.length">保留变量：{{ field.tokens.join('、') }}</small></label>
        <div class="copy-panel__save"><button type="submit" class="is-primary" :disabled="!dirty||state.busy||state.conflict||Object.keys(state.errors).length>0">{{ state.busy?'保存中…':'保存此区块' }}</button><button type="button" :disabled="!dirty||state.busy" @click="discard">还原</button></div>
      </form>
      <div v-else-if="state.tab==='comments'" class="copy-comments"><form @submit.prevent="comment"><label>备注 / 评论<textarea v-model="state.commentDraft" maxlength="2000" rows="3" placeholder="描述此处需要调整的内容…" :disabled="state.busy"/></label><button type="submit" class="is-primary" :disabled="state.busy||!state.commentDraft.trim()">提交评论</button></form><p v-if="!state.comments.length" class="copy-panel__hint">这里还没有评论。</p><article v-for="item in state.comments" :key="item.id" :class="{'is-resolved':item.resolved_at}"><header><strong>{{ item.actor }}</strong><time>{{ date(item.created_at) }}</time></header><p>{{ item.body }}</p><small>{{ context(item.context_json) }}</small><button v-if="!item.resolved_at" type="button" :disabled="state.busy" @click="resolve(item.id)">标记解决</button><span v-else class="copy-comment-resolved">已解决</span></article></div>
      <div v-else-if="state.tab==='history'" class="copy-history"><p class="copy-panel__hint">恢复历史内容后，保存为新版本，历史记录会保留。</p><p v-if="!state.versions.length" class="copy-panel__hint">尚无保存记录。</p><article v-for="version in state.versions" :key="version.id"><strong>v{{ version.revision }} · {{ version.actor }}</strong><time>{{ date(version.created_at) }}</time><button type="button" :disabled="state.busy" @click="restore(version)">预览此版本</button></article></div>
    </template>
    <p v-if="state.status" class="copy-panel__status" :class="{'is-conflict':state.conflict}" role="status">{{ state.status }}</p><button v-if="state.conflict" type="button" class="copy-panel__reload" :disabled="state.busy" @click="reload">载入最新版本</button>
    <footer v-if="reviewable" class="copy-panel__footer"><span>{{ state.session.role==='editor'?'可编辑文案与评论':'可查看与评论' }} · {{ state.connected?'已连接共享数据库':'连接中断' }}</span><button type="button" :disabled="state.busy" @click="refresh">刷新</button></footer>
  </section>
</template>
<script>
import {copyState,copyDirty,canEdit,canReview,editCopy,discardCopy,closeCopyBlock,saveCopy,submitComment,resolveComment,previewVersion,reloadCopy,loadBlock} from '@/copy/operations-copy'
export default {data:()=>({state:copyState}),computed:{editable(){return canEdit(this.state.selected.id)},reviewable(){return canReview(this.state.selected.id)},dirty:copyDirty},methods:{edit:editCopy,discard:discardCopy,close:closeCopyBlock,save:saveCopy,comment:submitComment,resolve:resolveComment,restore:previewVersion,reload:reloadCopy,async refresh(){try{await loadBlock();this.state.status='已刷新评论与记录。'}catch(error){this.state.status=error.message}},date(value){return new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value))},context(value){try{const c=JSON.parse(value);return [c.page,c.state].filter(Boolean).join(' · ')}catch(_){return ''}}}}
</script>
