r textarea{border-color:#d25b50}.copy-field small.copy-field__error{color:#c8463d}.copy-panel button.is-primary{color:#fff;background:#d75046;border-color:#d75046}.copy-panel__save{position:sticky;bottom:0;display:flex;gap:8px;background:#fbfcfeee;padding:14px 0;border-top:1px solid #eaecf0;z-index:1}.copy-panel__save>button:first-child{flex:1}.copy-panel__status{font-size:11px;line-height:18px;padding:11px 12px;border-radius:7px;background:#f1f5f0;color:#62805e;overflow-wrap:anywhere}.copy-panel__status.is-conflict{background:#fff6e8;color:#9c752e}.copy-panel__reload{width:100%}.copy-panel__footer{margin-top:24px;display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:10px;color:#a0a7b2}.copy-panel__footer button{padding:3px 7px;border:0;background:none}.copy-comments form>label{font-size:11px;color:#738090}.copy-comments textarea{margin:6px 0 10px}.copy-comments form>button{display:block;margin-left:auto}.copy-comments article,.copy-history article{padding:18px 0;border-bottom:1px solid #e9ecf0}.copy-comments article header{display:flex;justify-content:space-between;align-items:center;gap:8px}.copy-comments strong,.copy-history strong{font-size:11px;font-weight:600}.copy-comments time,.copy-history time{font-size:10px;color:#9ca4b0}.copy-comments article p{font-size:12px;line-height:20px;white-space:pre-wrap;overflow-wrap:anywhere;color:#5b6574;margin:9px 0}.copy-comments article>small{display:block;color:#9ca4b0;font-size:10px}.copy-comments article>button{font-size:10px;border:0;padding:4px 0;color:#bd7866;background:none}.copy-comments article.is-resolved{opacity:.65}.copy-comment-resolved{font-size:10px;color:#82967b}.copy-history article time{display:block;margin:4px 0 9px}.copy-history article button{font-size:10px}.copy-panel__locked{padding:20px 16px;background:#f4f6f8;border:1px solid #e8ebef;border-radius:9px;font-size:12px;color:#737e8d}.copy-panel__locked small{font-size:10px;color:#9da5b0}
